      "value": "import datetime, re
try:
    e = str(vars.get('id_event', 'none'))
    vars['id_event'] = 'none'
    vars['id_action'] = 'none'
    for k, v in [('id_phase', 'name'), ('id_name_asks', 1), ('id_declines', 0), ('talk_declines', 0), ('human_asks', 0), ('callback_invalid', 0), ('finish_state', 'open'), ('resolution_outcome', ''), ('resolution_reason', '')]:
        vars.setdefault(k, v)
    phase = str(vars['id_phase'])
    q = str(vars.get('id_question', 'none'))
    vars['id_question'] = 'none'
    vars['id_instruction'] = 'Ask only the missing part of the current question.'
    if vars.get('transfer_last_state') == 'failed':
        vars['transfer_last_state'] = 'none'
    lead = ''
    if q == 'ai' or (q == 'about' and phase == 'name'):
        lead = "I am Freya Bank's digital assistant. "
    elif q == 'scam':
        lead = "You can verify this call by phoning Freya Bank's customer service number. "
    elif q == 'unknown':
        lead = 'I do not have that information. '
    if q == 'about' and phase in ['dob', 'phone'] and e in ['question', 'name_question']:
        e = 'decline'
    if e == 'question' and phase == 'name':
        e = 'name_question'
    def finish(outcome, reason, instruction):
        vars['resolution_outcome'] = outcome
        vars['resolution_reason'] = reason
        vars['resolution_message'] = instruction
        vars['finish_state'] = 'ready'
        vars['id_instruction'] = instruction
    def repeat_name():
        n = int(vars.get('id_name_asks', 1))
        if n >= 2:
            finish('not_reached', 'unclear', lead + 'The name was not confirmed after two asks.')
        else:
            vars['id_name_asks'] = n + 1
            vars['id_instruction'] = lead + 'Ask the name-confirmation question once more; this is the second and final ask.'
    holidays = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    def business(d):
        return d.weekday() < 5 and d.isoformat() not in holidays
    def parse_day(s, today):
        try:
            s = str(s).strip().lower().replace(',', '')
            if s in ['today', 'tomorrow', 'day after tomorrow'] and isinstance(today, datetime.date):
                return today + datetime.timedelta(days=['today', 'tomorrow', 'day after tomorrow'].index(s))
            if re.fullmatch(r'\d{4}-\d{2}-\d{2}', s):
                return datetime.date.fromisoformat(s)
            m = re.fullmatch(r'(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})', s)
            if m:
                return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
            names = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
            m = re.fullmatch(r'(this|next)\s+(' + '|'.join(names) + ')', s)
            if m and isinstance(today, datetime.date):
                return today - datetime.timedelta(days=today.weekday()) + datetime.timedelta(days=names.index(m.group(2)) + (7 if m.group(1) == 'next' else 0))
            for fmt in ['%d %B %Y', '%B %d %Y', '%d %b %Y', '%b %d %Y']:
                try:
                    return datetime.datetime.strptime(s, fmt).date()
                except Exception:
                    pass
            return ''
        except Exception:
            return ''
    if e == 'wrong_number':
        finish('not_reached', 'wrong_number', 'Acknowledge the wrong number without account details.')
    elif e == 'deceased':
        finish('not_reached', 'deceased', 'Say exactly: I am sorry for your loss. Ask nothing else.')
    elif e == 'third_party':
        vars['id_phase'] = 'callback'
        vars['id_instruction'] = 'Disclose no reason or account information. Ask when the customer can be reached.'
    elif e == 'no_callback' and phase == 'callback':
        finish('not_reached', 'no_callback', 'No callback has been scheduled.')
    elif e == 'assist_yes':
        if phase == 'name':
            repeat_name()
        elif phase == 'dob':
            vars['id_instruction'] = 'Ask for the customer\'s date of birth. Agreement to assistance is not a security answer.'
        elif phase == 'phone':
            vars['id_instruction'] = 'Ask only for the last four digits of the phone number on file. Do not repeat the passed birth-date question.'
        else:
            vars['id_instruction'] = 'Ask when the customer can be reached. Agreement to assistance did not authorize a callback.'
    elif e == 'assist_no':
        vars['id_instruction'] = 'Acknowledge that they do not want further assistance. The failed transfer alone establishes no closing outcome; do not claim success, disclose account information, or repeat the transfer automatically.'
    elif e == 'human':
        if int(vars.get('human_asks', 0)) == 0:
            vars['human_asks'] = 1
            vars['id_instruction'] = 'Ask once: May I help you first? Agreement to this question is not name confirmation or a security answer.'
        else:
            vars['requested_queue'] = 'general'
            vars['id_action'] = 'transfer'
            vars['id_instruction'] = 'CALL transfer_to_agent now with queue general. Do not claim success before its result.'
    elif e == 'stop':
        n = int(vars.get('talk_declines', 0)) + 1
        vars['talk_declines'] = n
        if phase in ['dob', 'phone']:
            vars['id_declines'] = int(vars.get('id_declines', 0)) + 1
        if phase == 'callback':
            finish('not_reached', 'no_callback', 'No callback has been scheduled.')
        elif n >= 2 or (phase in ['dob', 'phone'] and int(vars['id_declines']) >= 2):
            finish('not_verified', 'declined', 'Respect the refusal; disclose no account details.')
        else:
            vars['id_instruction'] = 'Acknowledge briefly. Explain once that the questions protect the account, then ask only the current unanswered question. Disclose no call purpose.'
    elif e == 'decline' and phase in ['dob', 'phone']:
        n = int(vars.get('id_declines', 0)) + 1
        vars['id_declines'] = n
        if n >= 2:
            finish('not_verified', 'declined', 'Respect the identity refusal; disclose no account details.')
        else:
            vars['id_instruction'] = 'Explain once that the security questions protect the account. Ask only the current unanswered security question.'
    elif e == 'name_yes' and phase == 'name':
        vars['id_phase'] = 'dob'
        vars['id_instruction'] = 'Ask for the customer\'s date of birth. Do not ask for phone digits yet.'
    elif e in ['name_unclear', 'name_question'] and phase == 'name':
        repeat_name()
    elif e == 'answer' and phase in ['dob', 'phone']:
        s = str(vars.get('id_answer_text', '')).strip()
        answer = ''
        if phase == 'phone':
            words = dict(zero='0', oh='0', one='1', two='2', three='3', four='4', five='5', six='6', seven='7', eight='8', nine='9')
            parts = re.findall(r'[a-z]+|\d+', s.lower())
            digits = []
            valid = True
            for part in parts:
                if part in words:
                    digits.append(words[part])
                elif part.isdigit():
                    digits.append(part)
                else:
                    valid = False
            joined = ''.join(digits)
            if valid and re.fullmatch(r'\d{4}', joined):
                answer = joined
            else:
                vars['id_instruction'] = 'Ask only for the missing phone digits, or clarify the corrected four digits if too many were supplied. Do not validate a partial answer.'
        else:
            d = parse_day(s, '') if re.search(r'\d{4}', s) else ''
            if d:
                answer = d.isoformat()
            else:
                vars['id_instruction'] = 'Ask only for the missing or unclear birth-date component. Numeric order is day, month, year. Do not guess or validate a partial date.'
        if answer:
            vars['security_request'] = dict(field='date_of_birth' if phase == 'dob' else 'phone_last4', answer=answer)
            vars['id_action'] = 'verify'
            vars['id_instruction'] = 'CALL verify_identity now using the prepared customer-supplied answer. Do not repeat the question first.'
    elif e == 'callback' and phase == 'callback':
        now = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00')).replace(tzinfo=None)
        today = now.date()
        nxt = today + datetime.timedelta(days=1)
        while not business(nxt):
            nxt += datetime.timedelta(days=1)
        vars['callback_facts'] = dict(today=today.isoformat(), next_business_day=nxt.isoformat(), earliest_time='10:00', latest_time='19:00', strictly_after=now.isoformat())
        ds = str(vars.get('id_day_text', '')).strip()
        ts = str(vars.get('id_time_text', '')).strip()
        d = parse_day(ds, today)
        if not ds or not ts or not d or not re.fullmatch(r'\d{2}:\d{2}', ts):
            vars['id_instruction'] = 'Ask only for the missing or ambiguous exact callback day or time. Allowed dates are ' + today.isoformat() + ' or ' + nxt.isoformat() + ', 10:00 through 19:00, strictly later than now. Do not schedule yet.'
        else:
            valid_time = False
            try:
                stamp = datetime.datetime.combine(d, datetime.time.fromisoformat(ts))
                valid_time = d in [today, nxt] and '10:00' <= ts <= '19:00' and stamp > now
            except Exception:
                pass
            if valid_time:
                vars['authorized_callback'] = dict(date=d.isoformat(), time=ts)
                vars['id_action'] = 'callback'
                vars['id_instruction'] = 'CALL schedule_callback now for the validated customer-requested date ' + d.isoformat() + ' and time ' + ts + '.'
            else:
                n = int(vars.get('callback_invalid', 0)) + 1
                vars['callback_invalid'] = n
                vars['id_day_text'] = ''
                vars['id_time_text'] = ''
                if n >= 2:
                    finish('not_reached', 'no_callback', 'No callback was scheduled because both proposed times were outside the permitted window.')
                else:
                    vars['id_instruction'] = 'Explain the allowed window and ask once for another time: ' + today.isoformat() + ' or ' + nxt.isoformat() + ', 10:00 through 19:00, strictly later than ' + now.isoformat() + '.'
    elif e == 'question':
        vars['id_instruction'] = lead + 'Continue with only the current unanswered question. Do not disclose account details.'
    else:
        vars['id_instruction'] = lead + 'Ask only the current unanswered question; do not infer identity or call a bank tool without a prepared action.'
except Exception:
    vars['id_event'] = 'none'
    vars['id_action'] = 'none'
    vars['id_instruction'] = 'Say that the information could not be interpreted and ask for the missing exact detail. Do not call a bank tool or disclose account information.'
